// Builds the Edge Function's single file: the game engine + the day runner.
// usage: node tools/build-tick.js   (run again whenever engine.js or tick.src.js changes, then redeploy the function)
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..'), dir = path.join(root, 'supabase', 'functions', 'lm-hood-tick');
const out = ['// @ts-nocheck',
  '// GENERATED by tools/build-tick.js from engine.js and tick.src.js — edit those, not this file.',
  fs.readFileSync(path.join(root, 'engine.js'), 'utf8'),
  fs.readFileSync(path.join(dir, 'tick.src.js'), 'utf8')].join('\n');
fs.writeFileSync(path.join(dir, 'index.ts'), out);
console.log('supabase/functions/lm-hood-tick/index.ts', out.length, 'bytes');
